package cn.mop.api;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.sun.net.httpserver.HttpServer;
import org.junit.jupiter.api.*;
import org.springframework.mock.env.MockEnvironment;
import java.net.*;
import java.time.Duration;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;

class MonitoringPresetTest {
    static JsonNode golden(){try{return MonitoringPresetRegistry.JSON.readTree(Files.readString(Path.of("../../fixtures/monitoring-onboarding-golden.json")));}catch(Exception e){throw new RuntimeException(e);}}
    static ObjectNode config(String preset){for(JsonNode r:golden())if(r.path("config").path("targets").get(0).path("preset_id").asText().equals(preset))return (ObjectNode)r.get("config").deepCopy();throw new AssertionError();}
    static ObjectNode row(ObjectNode c){return (ObjectNode)c.withArray("targets").get(0);}
    static MonitoringPresetRegistry registry(ObjectNode c){return new MonitoringPresetRegistry(c.toString(),"[\""+row(c).path("endpoint").asText()+"\"]",row(c).get("target").isNull()?"[]":"[\""+row(c).get("target").asText()+"\"]");}
    static MonitoringPresetRegistry.Target first(MonitoringPresetRegistry r,ObjectNode c){return r.forTenant(row(c).get("tenant_id").asText()).get(0);}
    @Test void thirteenGoldenConfigurationsAndPythonHashesAgree(){assertEquals(13,golden().size());for(JsonNode g:golden()){ObjectNode c=(ObjectNode)g.get("config");var r=registry(c);var t=first(r,c);assertEquals(g.get("sha256").textValue(),t.hash());assertEquals(c,MonitoringPresetRegistry.JSON.valueToTree(t.configuration()));}}
    @Test void startupIsDisabledUnlessExplicitlyEnabled(){var c=new MonitoringPresetConfiguration();assertFalse(c.monitoringPresetProbeService(new MockEnvironment()).enabled());assertThrows(IllegalArgumentException.class,()->c.monitoringPresetProbeService(new MockEnvironment().withProperty("MOP_MONITORING_PRESET_TEST_ENABLED","yes")));assertThrows(IllegalArgumentException.class,()->c.monitoringPresetProbeService(new MockEnvironment().withProperty("MOP_MONITORING_PRESET_TEST_ENABLED","true")));}
    @Test void allowlistsDoNotDefaultToConfiguredAddresses(){ObjectNode c=config("linux-node");var r=new MonitoringPresetRegistry(c.toString(),"[]","[]");assertFalse(r.approved(first(r,c)));assertThrows(cn.mop.domain.DomainException.class,()->new MonitoringPresetProbeService(r,t->{throw new AssertionError();}).test(first(r,c)));}
    @Test void secretFieldsWrongTypesAndNoncanonicalAddressesFailClosed(){for(String endpoint:List.of("http://localhost:9100/metrics","http://169.254.169.254:9100/metrics","http://user:secret@192.0.2.10:9100/metrics","http://192.0.2.10:9100/metrics?x=secret","http://192.0.2.10:9100/wrong","http://224.1.1.1:9100/metrics","http://0.0.0.0:9100/metrics")){var c=config("linux-node");row(c).put("endpoint",endpoint);assertThrows(IllegalArgumentException.class,()->registry(c));}var c=config("linux-node");row(c).put("token","secret");assertThrows(IllegalArgumentException.class,()->registry(c));}
    @Test void oversizedVersionCannotWrapToOne(){var c=config("linux-node");c.put("version",4294967297L);assertThrows(IllegalArgumentException.class,()->registry(c));}
    @Test void explicitCadenceAndTimeoutAreRequired(){for(int interval:List.of(0,4,3601)){var c=config("linux-node");row(c).put("interval_seconds",interval);assertThrows(IllegalArgumentException.class,()->registry(c));}var c=config("linux-node");row(c).put("enabled",true);assertThrows(IllegalArgumentException.class,()->registry(c));}
    @Test void duplicateFieldsDocumentsAndTargetsAreRejected(){var c=config("linux-node");assertThrows(IllegalArgumentException.class,()->new MonitoringPresetRegistry(c+" {}","[]","[]"));assertThrows(IllegalArgumentException.class,()->new MonitoringPresetRegistry(c.toString().replace("\"version\":1","\"version\":1,\"version\":1"),"[]","[]"));c.withArray("targets").add(row(c).deepCopy());assertThrows(IllegalArgumentException.class,()->registry(c));}
    @Test void snmpRequiresNamedAuthAndIndependentDownstreamAuthorization(){var c=config("network-snmp");var r=new MonitoringPresetRegistry(c.toString(),"[\""+row(c).get("endpoint").asText()+"\"]","[]");assertFalse(r.approved(first(r,c)));row(c).putNull("auth_profile");assertThrows(IllegalArgumentException.class,()->registry(c));}
    @Test void returnedConfigurationCannotMutateRegisteredTarget(){var c=config("linux-node");var r=registry(c);var t=first(r,c);String h=t.hash();((Map<?,?>)t.configuration()).clear();row(c).put("enabled",true);assertEquals(h,t.hash());assertFalse(MonitoringPresetRegistry.JSON.valueToTree(t.configuration()).path("targets").get(0).get("enabled").booleanValue());assertFalse(t.toString().contains(t.assetId()));}
    @Test void tenantsNeverFallBackToOtherTargets(){var c=config("linux-node");var r=registry(c);assertTrue(r.forTenant("other").isEmpty());assertTrue(r.find("other",row(c).get("id").textValue()).isEmpty());}
    @Test void everyPrometheusPresetRecognizesItsOwnMetric(){for(var p:MonitoringPresetRegistry.presets().values())if(p.engine().equals("prometheus")){var out=MonitoringPresetProbeService.metrics((p.metrics().get(0)+" 1\n").getBytes(StandardCharsets.UTF_8),p);assertEquals(1,out.get("sample_count"));assertEquals(false,out.get("metric_values_stored"));}}
    @Test void malformedMissingDuplicateOrNonfiniteSamplesNeverPass(){var p=MonitoringPresetRegistry.presets().get("linux-node");for(String s:List.of("","<html>secret</html>","up 1","node_cpu_seconds_total NaN","node_cpu_seconds_total +Inf","node_cpu_seconds_total{oops} 1","node_cpu_seconds_total{a=\"1\",a=\"2\"} 1","node_cpu_seconds_total{a=\"1\",b=\"2\"} 1\nnode_cpu_seconds_total{b=\"2\",a=\"1\"} 2","node_cpu_seconds_total 1\nnode_cpu_seconds_total 2"))assertThrows(MonitoringPresetProbeService.ProbeFailure.class,()->MonitoringPresetProbeService.metrics(s.getBytes(StandardCharsets.UTF_8),p));}
    @Test void zeroBackendUpIsFailureNotValidHealthySample(){var p=MonitoringPresetRegistry.presets().get("postgresql");assertEquals("TARGET_PROBE_FAILED",assertThrows(MonitoringPresetProbeService.ProbeFailure.class,()->MonitoringPresetProbeService.metrics("pg_up 0".getBytes(StandardCharsets.UTF_8),p)).reason);}
    @Test void globalProbeSlotRejectsConcurrentWorkAndReleasesAfterFailure()throws Exception{var c=config("linux-node");var r=registry(c);CountDownLatch started=new CountDownLatch(1),release=new CountDownLatch(1);var s=new MonitoringPresetProbeService(r,t->{started.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}return MonitoringPresetProbeService.base(t);});ExecutorService pool=Executors.newSingleThreadExecutor();try{var f=pool.submit(()->s.test(first(r,c)));assertTrue(started.await(2,TimeUnit.SECONDS));assertEquals(429,assertThrows(cn.mop.domain.DomainException.class,()->s.test(first(r,c))).status);release.countDown();f.get();assertNotNull(s.test(first(r,c)));}finally{release.countDown();pool.shutdownNow();}}

    HttpServer server;AtomicInteger status;AtomicReference<String> content,type;AtomicInteger delay,hits;AtomicReference<String> seenPath;
    void start()throws Exception{status=new AtomicInteger(200);content=new AtomicReference<>("node_cpu_seconds_total{cpu=\"0\"} 12\n");type=new AtomicReference<>("text/plain");delay=new AtomicInteger();hits=new AtomicInteger();seenPath=new AtomicReference<>();server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",exchange->{hits.incrementAndGet();seenPath.set(exchange.getRequestURI().toString());try{if(delay.get()>0)Thread.sleep(delay.get());byte[] bytes=content.get().getBytes(StandardCharsets.UTF_8);exchange.getResponseHeaders().set("Content-Type",type.get());exchange.getResponseHeaders().set("Location","http://192.0.2.99:1/no-follow");exchange.sendResponseHeaders(status.get(),bytes.length);exchange.getResponseBody().write(bytes);}catch(Exception ignored){}finally{exchange.close();}});server.start();}
    Map<String,Object> probe(String preset){var c=config(preset);var p=MonitoringPresetRegistry.presets().get(preset);row(c).put("endpoint",(p.kind().equals("tcp")?"tcp":"http")+"://127.0.0.1:"+server.getAddress().getPort()+(p.path()==null?"":p.path())).put("timeout_seconds",1);var r=registry(c);return new MonitoringPresetProbeService(r,MonitoringPresetProbeService.network()).test(first(r,c));}
    @AfterEach void stop(){if(server!=null)server.stop(0);}
    @Test void actualLocalHttpReturnsOnlyOneShotSummary()throws Exception{start();var out=probe("linux-node");assertEquals("SAMPLE_VERIFIED_ONCE",out.get("probe_status"));assertEquals(1,hits.get());assertEquals(false,out.get("health_verified"));assertEquals(false,out.get("continuous_collection_verified"));assertFalse(out.toString().contains("cpu="));}
    @Test void actualRedirectAndLoginHtmlCannotPass()throws Exception{start();status.set(302);assertEquals("HTTP_STATUS_REJECTED",probe("linux-node").get("reason"));assertEquals(1,hits.get());status.set(200);type.set("text/html");content.set("<html>secret</html>");var out=probe("linux-node");assertEquals("CONTENT_TYPE_REJECTED",out.get("reason"));assertFalse(out.toString().contains("secret"));}
    @Test void actualBlackboxUsesOnlyExplicitDownstream()throws Exception{start();content.set("probe_success 1\n");assertEquals("SAMPLE_VERIFIED_ONCE",probe("http-service").get("probe_status"));assertTrue(seenPath.get().contains("module=mop_http"));assertTrue(seenPath.get().contains("target=https%3A%2F%2F192.0.2.20%3A443%2F"));}
    @Test void actualSlowHeadersAreBoundedByWholeRequestDeadline()throws Exception{start();delay.set(1800);long before=System.nanoTime();assertEquals("FAILED",probe("linux-node").get("probe_status"));assertTrue(Duration.ofNanos(System.nanoTime()-before).toMillis()<1600);}
    @Test void actualOversizedResponseCannotBecomePartialSuccess()throws Exception{start();content.set("#"+"x".repeat(MonitoringPresetProbeService.MAX_BYTES));assertEquals("FAILED",probe("linux-node").get("probe_status"));}
    @Test void actualTcpConnectivityNeverClaimsAgentAuthentication()throws Exception{start();var out=probe("zabbix-linux");assertEquals("TCP_REACHABLE_PROTOCOL_UNVERIFIED",out.get("probe_status"));assertNull(out.get("sample_count"));}
}
